const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Geometry for Al Bayda, Libya. A buffer is used to average over the city area.
  const geometry = ee.Geometry.Point([21.7551, 32.7634]).buffer(5000); // 5km buffer

  // Dates of interest
  const dateBefore = '2023-09-08';
  const dateAfter = '2023-09-13';

  // 2. Data Acquisition & Processing Function
  // VNP46A2 "Black Marble" is a high-quality daily nighttime lights product.
  const collectionId = 'NOAA/VIIRS/DNB/COMPOSITE_V2/VNP46A2';
  const band = 'DNB_BRDF_Corrected_NTL';
  const qualityBand = 'Mandatory_Quality_Flag';

  const processDate = (date) => {
    const image = ee.ImageCollection(collectionId)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .select([band, qualityBand])
      .first();

    // The function needs to return a value, even if the image is null
    if (!image) {
      return null;
    }

    // Mask pixels with low quality. Good quality pixels have a flag value of 0.
    const qualityMask = image.select(qualityBand).eq(0);
    return image.select(band).updateMask(qualityMask);
  };

  // 3. Get Images for the two dates
  const imageBefore = processDate(dateBefore);
  const imageAfter = processDate(dateAfter);

  // Check if images exist for the specified dates.
  if (!imageBefore || !imageAfter) {
    console.log(`Image missing for one or both dates: Before=${!!imageBefore}, After=${!!imageAfter}`);
    console.log('A');
    return;
  }

  // 4. Calculation
  const scale = 500; // VNP46A2 native resolution is ~500m
  const reducer = ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
  });

  const statsBefore = imageBefore.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const statsAfter = imageAfter.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  // Execute the computations
  const beforeResult = await ee.data.computeValue(statsBefore);
  const afterResult = await ee.data.computeValue(statsAfter);

  const meanBefore = beforeResult[band + '_mean'];
  const countBefore = beforeResult[band + '_count'];
  const meanAfter = afterResult[band + '_mean'];
  const countAfter = afterResult[band + '_count'];

  // 5. Validation & Final Answer
  if (countBefore === 0 || countAfter === 0) {
    console.log(`No valid pixels found for one or both dates.`);
    console.log(`Pixels on ${dateBefore}: ${countBefore}`);
    console.log(`Pixels on ${dateAfter}: ${countAfter}`);
    console.log('C2');
    return;
  }

  if (meanBefore === null || meanAfter === null) {
      console.log('Calculation resulted in null.');
      console.log(`Radiance on ${dateBefore}: ${meanBefore}`);
      console.log(`Radiance on ${dateAfter}: ${meanAfter}`);
      console.log('C3');
      return;
  }

  console.log(`Nighttime light radiance (nW/cm²/sr) in Al Bayda:`);
  console.log(`${dateBefore}: ${meanBefore.toFixed(2)} (from ${countBefore} pixels)`);
  console.log(`${dateAfter}: ${meanAfter.toFixed(2)} (from ${countAfter} pixels)`);

  const pctChange = ((meanAfter - meanBefore) / meanBefore) * 100;
  console.log(`Change: ${pctChange.toFixed(1)}%`);

  if (meanAfter < meanBefore) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during Earth Engine initialization or analysis.');
    console.error(e);
    console.log('D');
  }
}

initEE();
